import{_ as e,o as t,c as r,a2 as l}from"./chunks/framework.Ca9F9Y59.js";const i="/k3gdb/assets/AI_%E5%BD%A2%E5%BC%8F%E5%8C%96%E8%AF%81%E6%98%8E_%E8%BF%AD%E4%BB%A3%E9%AA%8C%E8%AF%81%E6%B5%81%E7%A8%8B.DF_uS3DQ.png",o="/k3gdb/assets/AgentSentinel_%E5%9B%9B%E7%BB%84%E4%BB%B6%E5%8D%8F%E5%90%8C%E5%AE%89%E5%85%A8%E7%9B%91%E6%B5%8B%E6%9E%B6%E6%9E%84.ph_L6zZY.png",b=JSON.parse('{"title":"AI 辅助程序验证","description":"","frontmatter":{},"headers":[],"relativePath":"2026-11-02-大模型与形式化验证论坛报告.md","filePath":"2026-11-02-大模型与形式化验证论坛报告.md"}'),n={name:"2026-11-02-大模型与形式化验证论坛报告.md"};function h(s,a,d,c,p,u){return t(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="ai-辅助程序验证" tabindex="-1">AI 辅助程序验证 <a class="header-anchor" href="#ai-辅助程序验证" aria-label="Permalink to &quot;AI 辅助程序验证&quot;">​</a></h1><h2 id="研究背景" tabindex="-1">研究背景 <a class="header-anchor" href="#研究背景" aria-label="Permalink to &quot;研究背景&quot;">​</a></h2><p>形式化验证的目标，是通过数学证明来判断程序是否满足预先定义的性质。</p><p>传统测试只能检查有限数量的输入，而形式化证明可以在明确的模型和假设下，对所有符合要求的输入进行推理。</p><p>在形式化方法中，常用 Hoare Triple（霍尔三元组）表示这种关系： 其中：</p><ul><li>(P)：程序执行前必须满足的条件。</li><li>(C)：待验证程序。</li><li>(Q)：程序执行后必须满足的条件。</li></ul><p>但是，证明代码通常需要人工编写，成本可能远远超过程序本身，大概是1：20的代码比例。</p><h2 id="研究目标" tabindex="-1">研究目标 <a class="header-anchor" href="#研究目标" aria-label="Permalink to &quot;研究目标&quot;">​</a></h2><p>希望将大模型与成熟的程序验证工具结合，其基本思想是：人类定义程序需要满足的性质，AI 生成证明步骤，并由定理证明器检查是否成立。</p><p>因此，系统的可靠性主要来自形式化证明检查机制，而不是大模型推断</p><h2 id="核心方法" tabindex="-1">核心方法 <a class="header-anchor" href="#核心方法" aria-label="Permalink to &quot;核心方法&quot;">​</a></h2><p><img src="'+i+'" alt="AutoSD"></p><h2 id="实验结果" tabindex="-1">实验结果 <a class="header-anchor" href="#实验结果" aria-label="Permalink to &quot;实验结果&quot;">​</a></h2><p>说明 AI 已经能够完成一些经典算法的功能正确性证明，比如插入排序算法</p><p>相比 Anthropic 的研究，重要的差别是：函数规约允许用数学语言，来定义程序的复杂功能。它可以把数学公式来作为规约，要求返回值满足相应数学性质。而只依赖有限的测试样例作为规约，很难完整表达这类数学通用性质。</p><h2 id="尚未解决的问题" tabindex="-1">尚未解决的问题 <a class="header-anchor" href="#尚未解决的问题" aria-label="Permalink to &quot;尚未解决的问题&quot;">​</a></h2><ol><li>正确的规约从何而来？证明器能够证明程序满足某个规约，但不能保证这就是用户真正想要的功能</li><li>复杂程序的自动证明仍可能失败。AI 即使可以编写证明代码，不代表能发现所有复杂程序所需的条件。</li><li>如果编译器或底层运行环境存在错误，仅凭源码级证明不能保证最终机器代码的全部行为</li><li>QCP 等程序验证工具非常重要，虽然有ai辅助，但仍十分依赖成熟的验证基础设施。</li></ol><p>核心结论：AI 解决的是证明过程中的人工成本，形式化工具提供正确性检查，复杂功能规约仍然是整个验证体系的基础。</p><h1 id="agentsentinel——面向-computer-use-agent-的实时安全防御" tabindex="-1">AgentSentinel——面向 Computer-Use Agent 的实时安全防御 <a class="header-anchor" href="#agentsentinel——面向-computer-use-agent-的实时安全防御" aria-label="Permalink to &quot;AgentSentinel——面向 Computer-Use Agent 的实时安全防御&quot;">​</a></h1><h2 id="研究背景-1" tabindex="-1">研究背景 <a class="header-anchor" href="#研究背景-1" aria-label="Permalink to &quot;研究背景&quot;">​</a></h2><p>Agent 带来了新的安全威胁，传统大模型主要生成文字。但 Computer-Use Agent 已经能够完成多种复杂行为，执行 Shell 命令，访问和修改文件，操作浏览器，调用第三方工具，访问网络服务等，这使得模型的错误行为可能产生真实的系统副作用。</p><ol><li>传统防御机制无法充分理解 Agent 的行为意图。</li><li>工具种类繁多，无法逐一编写安全策略</li><li>实时审计会产生性能开销</li></ol><h2 id="研究目标-1" tabindex="-1">研究目标 <a class="header-anchor" href="#研究目标-1" aria-label="Permalink to &quot;研究目标&quot;">​</a></h2><p>设计一个尽量不改变现有 Agent 运行架构的安全防御框架，实现：系统行为实时观测 → 威胁识别 → 安全审计 → 操作拦截或恢复。同时希望同时兼顾安全性、通用性和性能效率。</p><h2 id="核心方法-1" tabindex="-1">核心方法 <a class="header-anchor" href="#核心方法-1" aria-label="Permalink to &quot;核心方法&quot;">​</a></h2><p><img src="'+o+'" alt="AutoSD"> 同时防御模块内部也利用了大模型，通过理解用户任务和操作上下文，判断某个系统行为是否危险</p><h1 id="c2btor——基于硬件模型检查的-c-程序验证" tabindex="-1">C2Btor——基于硬件模型检查的 C 程序验证 <a class="header-anchor" href="#c2btor——基于硬件模型检查的-c-程序验证" aria-label="Permalink to &quot;C2Btor——基于硬件模型检查的 C 程序验证&quot;">​</a></h1><h2 id="研究背景-2" tabindex="-1">研究背景 <a class="header-anchor" href="#研究背景-2" aria-label="Permalink to &quot;研究背景&quot;">​</a></h2><p>新算法很难直接在传统程序验证工具之间复用</p><h2 id="研究目标-2" tabindex="-1">研究目标 <a class="header-anchor" href="#研究目标-2" aria-label="Permalink to &quot;研究目标&quot;">​</a></h2><p>把 C 程序转换成硬件模型，让成熟的硬件验证算法来证明 C 程序是否安全，提升 C 程序的安全性质验证能力</p><h2 id="核心方法-2" tabindex="-1">核心方法 <a class="header-anchor" href="#核心方法-2" aria-label="Permalink to &quot;核心方法&quot;">​</a></h2><p>把硬件模型检查的成熟技术迁移到 C 程序验证中</p><h1 id="基于安全属性的-rust-程序验证" tabindex="-1">基于安全属性的 Rust 程序验证 <a class="header-anchor" href="#基于安全属性的-rust-程序验证" aria-label="Permalink to &quot;基于安全属性的 Rust 程序验证&quot;">​</a></h1><h2 id="研究背景-3" tabindex="-1">研究背景 <a class="header-anchor" href="#研究背景-3" aria-label="Permalink to &quot;研究背景&quot;">​</a></h2><p>研究背景：Rust 为什么还需要安全验证？ Rust 通过所有权、借用检查和类型系统提供较强的内存安全保障。但 Unsafe API 仍然可能引入未定义行为。</p><h2 id="核心方法-3" tabindex="-1">核心方法 <a class="header-anchor" href="#核心方法-3" aria-label="Permalink to &quot;核心方法&quot;">​</a></h2><ol><li>统一描述和维护 Unsafe API 的安全要求</li><li>复用这些安全要求，自动验证函数调用是否满足相应的安全契约 创新点：把原本供人阅读的安全文档转化为可自动验证的安全契约，减少人工编写验证代码的成本。</li></ol>',38)])])}const m=e(n,[["render",h]]);export{b as __pageData,m as default};
